// Doctor dashboard laid out per Family_Veda_Doctor_Mockup_v2. Data: GET /dashboard/doctor and
// GET /doctors/me/family-requests. Agent traces stay on the Approvals screen, not here.
import { useCallback, useEffect, useState } from 'react'
import { Link } from 'react-router-dom'

import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { threePortalApi, type DoctorDashboardSummaryDto, type DoctorRequestDto } from '../../services/apiClient'
import { extractErrorMessage } from '../family/threePortalUtils'
import { Badge, Metric } from '../dashboard/dashboardParts'
import { appointmentTone, greeting, shortDate, shortTime } from '../dashboard/dashboardFormat'

export function DoctorDashboardPanel() {
  const [data, setData] = useState<DoctorDashboardSummaryDto | null>(null)
  const [pendingRequests, setPendingRequests] = useState<DoctorRequestDto[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [message, setMessage] = useState('')

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const [{ data: dashboard }, { data: requests }] = await Promise.all([
        threePortalApi.getDoctorDashboard(),
        threePortalApi.getMyFamilyDoctorRequests(),
      ])
      setData(dashboard)
      setPendingRequests(requests)
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  async function respond(request: DoctorRequestDto, accept: boolean) {
    try {
      if (accept) await threePortalApi.acceptFamilyDoctorRequest(request.id)
      else await threePortalApi.declineFamilyDoctorRequest(request.id)
      setMessage(accept ? `Accepted request from ${request.familyName}.` : `Declined request from ${request.familyName}.`)
      await load()
    } catch (error) {
      setMessage(extractErrorMessage(error, 'Request could not be updated.'))
    }
  }

  if (status === 'loading') return <LoadingState label="Loading your dashboard" />
  if (status === 'error') return <ErrorState message="Dashboard summary could not be loaded." onRetry={() => void load()} />
  if (!data) return <EmptyState title="No dashboard data" message="Nothing to show yet." />

  const now = Date.now()
  const nextToday = data.todayAppointments.find(
    (item) => new Date(item.startsAt).getTime() >= now && (item.status === 'Confirmed' || item.status === 'Requested'),
  )
  const priority = data.priorityOpenCases ?? 0
  const families = data.families ?? []
  const activity = data.activity ?? []
  const verified = (data.verificationStatus ?? 'Verified') === 'Verified'

  return (
    <div className="fv-dash" aria-label="Doctor dashboard">
      {message && <p role="status" className="status-banner">{message}</p>}

      <section className="fv-hero" aria-label="Dashboard overview">
        <div>
          <p className="fv-eyebrow">Doctor workspace</p>
          <h1>{greeting()}, {data.doctorDisplayName ?? 'Doctor'}</h1>
          <p>{data.specialty ? `${data.specialty} · ` : ''}Review today&apos;s appointments, families and clinical approval work.</p>
        </div>
        <Badge tone={verified ? 'ok' : 'warn'}>{verified ? 'Clinical access active' : 'Verification pending'}</Badge>
      </section>

      <section className="fv-metrics" aria-label="Doctor metrics">
        <Metric
          label="Today's Appointments"
          to="/calendar"
          value={data.todayAppointments.length}
          badge={nextToday ? <Badge tone="info">Next {shortTime(nextToday.startsAt)}</Badge> : <Badge tone="muted">No more today</Badge>}
        />
        <Metric
          label="Pending Approvals"
          to="/approvals"
          value={data.pendingApprovals}
          badge={data.pendingApprovals > 0 ? <Badge tone="warn">Action required</Badge> : <Badge tone="ok">Up to date</Badge>}
        />
        <Metric
          label="Open Triage Cases"
          to="/cases"
          value={data.openCases}
          badge={priority > 0 ? <Badge tone="danger">{priority} priority</Badge> : <Badge tone="info">Routine only</Badge>}
        />
        <Metric
          label="Family Requests"
          to="/families?tab=requests"
          value={pendingRequests.length}
          badge={pendingRequests.length > 0 ? <Badge tone="warn">Pending</Badge> : <Badge tone="muted">None</Badge>}
        />
      </section>

      <div className="fv-grid2">
        <section className="fv-panel" aria-label="Today's schedule">
          <div className="fv-head">
            <div>
              <p className="fv-eyebrow">Today</p>
              <h2>Today&apos;s Schedule</h2>
            </div>
            <Link className="fv-btn" to="/doctor-calendar">Open Calendar</Link>
          </div>
          {data.todayAppointments.length === 0 ? (
            <EmptyState title="No appointments today" message="Confirmed appointments for today will show here." />
          ) : (
            <div className="fv-stack">
              {data.todayAppointments.map((appointment) => (
                <div className="fv-item" key={appointment.id}>
                  <div className="fv-row">
                    <b>{shortTime(appointment.startsAt)} · {appointment.familyName} · {appointment.memberDisplayName}</b>
                    <Badge tone={appointmentTone(appointment.status)}>{appointment.status}</Badge>
                  </div>
                  <p>{appointment.reason}</p>
                </div>
              ))}
            </div>
          )}
        </section>

        <aside className="fv-panel" aria-label="Needs attention">
          <div className="fv-head">
            <div>
              <p className="fv-eyebrow">Priority</p>
              <h2>Needs Attention</h2>
            </div>
          </div>
          <div className="fv-stack">
            {priority > 0 && (
              <div className="fv-item">
                <div className="fv-row"><b>Priority triage case{priority === 1 ? '' : 's'}</b><Badge tone="danger">Priority</Badge></div>
                <p>Clinical review waiting.</p>
                <Link className="fv-btn" to="/cases">Open</Link>
              </div>
            )}
            {data.pendingApprovals > 0 && (
              <div className="fv-item">
                <div className="fv-row"><b>{data.pendingApprovals} approval decision{data.pendingApprovals === 1 ? '' : 's'}</b><Badge tone="warn">Pending</Badge></div>
                <p>Drafts remain doctor-only until you decide.</p>
                <Link className="fv-btn" to="/approvals">Review</Link>
              </div>
            )}
            {pendingRequests.length > 0 && (
              <div className="fv-item">
                <div className="fv-row"><b>New family request</b><Badge tone="info">New</Badge></div>
                <p>Long-term family doctor request.</p>
              </div>
            )}
            {priority === 0 && data.pendingApprovals === 0 && pendingRequests.length === 0 && <p>Nothing needs your attention right now.</p>}
          </div>
        </aside>
      </div>

      <div className="fv-gridhalf">
        <section className="fv-panel" aria-label="My families">
          <div className="fv-head">
            <div>
              <p className="fv-eyebrow">Longitudinal care</p>
              <h2>My Families</h2>
            </div>
            <Link className="fv-btn" to="/families">View All</Link>
          </div>
          {families.length === 0 ? (
            <EmptyState title="No assigned families" message={`${data.assignedFamilies} active assignments.`} />
          ) : (
            <div className="fv-scroll">
              <table className="fv-table">
                <thead>
                  <tr><th>Family</th><th>Members</th><th>Last Visit</th><th>Next</th></tr>
                </thead>
                <tbody>
                  {families.map((family) => (
                    <tr key={family.familyId}>
                      <td><b>{family.familyName}</b></td>
                      <td>{family.memberCount}</td>
                      <td>{shortDate(family.lastVisit)}</td>
                      <td>{shortDate(family.nextAppointment)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
        <section className="fv-panel" aria-label="Clinical timeline">
          <div className="fv-head">
            <div>
              <p className="fv-eyebrow">Recent permitted activity</p>
              <h2>Clinical Timeline</h2>
            </div>
          </div>
          {activity.length === 0 ? (
            <EmptyState title="No recent activity" message="Appointments and granted cases appear here." />
          ) : (
            <ul className="fv-timeline">
              {activity.map((entry, index) => (
                <li className="fv-event" key={`${entry.title}-${index}`}>
                  <strong>{entry.title}</strong>
                  <p>{[entry.subject, shortDate(entry.occurredAt)].filter(Boolean).join(' · ')}</p>
                </li>
              ))}
            </ul>
          )}
        </section>
      </div>

      <section className="fv-panel" aria-label="Family doctor requests">
        <div className="fv-head">
          <div>
            <p className="fv-eyebrow">Assigned care</p>
            <h2>Family Requests</h2>
          </div>
        </div>
        {pendingRequests.length === 0 ? (
          <EmptyState title="No pending requests" message="Families that request you as their doctor appear here." />
        ) : (
          <div className="fv-stack">
            {pendingRequests.map((request) => (
              <div className="fv-item" key={request.id}>
                <div className="fv-row">
                  <div>
                    <b>{request.familyName}</b>
                    <p>{request.memberCount} members · Long-term family doctor request{request.message ? ` · “${request.message}”` : ''}</p>
                  </div>
                  <Badge tone="warn">Pending</Badge>
                </div>
                <div className="fv-actions">
                  <button className="fv-btn fv-btn--primary" type="button" onClick={() => void respond(request, true)}>Accept</button>
                  <button className="fv-btn" type="button" onClick={() => void respond(request, false)}>Decline</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  )
}
